function GetTrainset(Loco, Carts)
    return ConcatArray(GetLoco(Loco), GetCarts(Carts))
end


function GetLoco(trainset)
    if trainset =="M_E6ACTa" then
        return {
            CreateNewSpawnFullVehicleDescriptor(LocomotiveNames.ET25_002, false, "", 0, BrakeRegime.G),
        }
    elseif trainset =="M_ET22" then
        return {
            CreateNewSpawnFullVehicleDescriptor(LocomotiveNames.ET22_256, false, "", 0, BrakeRegime.G)
        }
    elseif trainset =="M_CD163" then
        return {
            CreateNewSpawnFullVehicleDescriptor(LocomotiveNames.CD163_041_7, false, "", 0, BrakeRegime.R),
        }
    elseif trainset =="M_E186" then
        return {
            CreateNewSpawnFullVehicleDescriptor(LocomotiveNames.EU43_005, false, "", 0, BrakeRegime.G)
        }
    elseif trainset =="M_EU07" then
        return {
            CreateNewSpawnFullVehicleDescriptor(LocomotiveNames.EU07_193, false, "", 0, BrakeRegime.G)
        }
    elseif trainset =="M_EU07x2" then
        return {
            CreateNewSpawnFullVehicleDescriptor(LocomotiveNames.EU07_070, false, "", 0, BrakeRegime.G),
            CreateNewSpawnFullVehicleDescriptor(LocomotiveNames.EU07_153, false, "", 0, BrakeRegime.G)
        }
    elseif trainset =="M_Ty2" then
        return {
            CreateNewSpawnFullVehicleDescriptor(LocomotiveNames.Ty2_477, false, "", 0, BrakeRegime.G)
            
        }
    end
end

